ROOT=Path(__file__).resolve().parents[1];OUT=Path(__file__).resolve().parent;source=ROOT/'runs/relative_joint_reader_20261109/results.json';results=json.loads(source.read_text(encoding='utf8'));examples=[]
for r in results['records']:
    if r['uid'] not in [4982,17832]:continue
    scores={c['kind']:c['maximum'] for c in r['variants']['C34']};assert scores['own']<scores['foreign'];examples.append(dict(uid=r['uid'],**scores))
